import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"2017年 · 税改大年","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2017年.md","filePath":"05_quotes/by-year/2017年.md"}'),l={name:"05_quotes/by-year/2017年.md"};function u(c,e,p,q,s,_){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_2017年-·-税改大年" tabindex="-1">2017年 · 税改大年 <a class="header-anchor" href="#_2017年-·-税改大年" aria-label="Permalink to &quot;2017年 · 税改大年&quot;">​</a></h1><blockquote><p>2017年远非寻常之年：我们收益的很大一部分并非来自伯克希尔内部任何人的作为。653亿美元的增幅是真实的——请放心。但其中仅360亿美元来自伯克希尔的运营业务。其余290亿美元是去年12月国会重写美国税法时送给我们的。——巴菲特（87岁）</p></blockquote><p>本页收录2017年致股东信中的经典语录。本年以企业税改为最大亮点，十年赌局正式收官，同时首次提出用市场价格替代账面价值作为业绩衡量标准。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>在投资过程中，他们研究10-K文件，访谈管理层，阅读行业期刊，并与华尔街分析师交流。与此同时，Protégé和我既不依赖研究、洞察力，也不需要才华，在十年间只做了一个投资决策。</p></blockquote><blockquote><p>投资是一种今天放弃消费以试图在将来获得更多消费的活动。&quot;风险&quot;是这种目标无法实现的可能性。按此标准，2012年所谓&quot;无风险&quot;的长期债券作为投资比普通股长期投资的风险要大得多。</p></blockquote><blockquote><p>坚持大的、&quot;简单&quot;的决策，避免频繁活动。</p></blockquote><blockquote><p>短期内，市场是一台投票机；但从长期来看，它变成一台称重机。</p></blockquote><blockquote><p>查理和我相信，我们的被投资企业保留的收益将随着时间的推移转化为伯克希尔的相应资本收益。</p></blockquote><blockquote><p>别问理发师你是否需要理发。</p></blockquote><blockquote><p>在伯克希尔，最重要的是我们标准化每股盈利能力的变化。这一指标是我的长期搭档查理·芒格和我所关注的——我们也希望您这样做。</p></blockquote><blockquote><p>这张表提供了我能提出的最强有力的论据，反对使用借来的钱购买股票。根本无法预测股票在短期内会跌多远。</p></blockquote><blockquote><p>我们两人都相信，为了得到你不需要的东西而冒险失去你已有的和需要的东西，是不明智的。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2017年伯克希尔每股账面价值增长23%，略高于标普500的21.8%。净资产增加653亿美元，其中290亿来自特朗普税改（企业税率从35%降至21%）。十年赌局正式收官：标普500年均收益8.5%，而五只对冲基金组合最高仅6.5%。巴菲特宣布不再以每股账面价值作为主要业绩衡量指标，任命阿吉特·贾因和格雷格·阿贝尔为副董事长。年末持有1160亿美元现金。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/2017年/翻译.html">01_letters/2017年/翻译</a> · <a href="/01_letters/2017年/核心总结.html">01_letters/2017年/核心总结</a> · <a href="/01_letters/2017年/思维导图.html">01_letters/2017年/思维导图</a></p>',20)])])}const n=t(l,[["render",u]]);export{h as __pageData,n as default};
